A=library-application/src/main/java/$B/application/loan
cat > $A/BorrowBook.java <<'E'
package com.example.library.application.loan;

import com.example.library.domain.loan.*;
import java.time.Clock;

public final class BorrowBook {
    static final int MAX_LOANS_PER_MEMBER = 3;

    private final LoanRepository loans;
    private final Clock clock;

    public BorrowBook(LoanRepository loans, Clock clock) {
        this.loans = loans;
        this.clock = clock;
    }

    public void execute(LoanId loanId, MemberId memberId, Isbn isbn) {
        if (loans.countByMember(memberId) >= MAX_LOANS_PER_MEMBER) {
            throw new LoanLimitExceededException(memberId, MAX_LOANS_PER_MEMBER);
        }
        if (loans.existsByIsbn(isbn)) {
            throw new BookAlreadyOnLoanException(isbn);
        }
        loans.save(Loan.borrow(loanId, memberId, isbn, clock.instant()));
    }
}
E

