cat > $I/LoanEntity.java <<E
package $IP;

import jakarta.persistence.*;
import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "loans", uniqueConstraints = @UniqueConstraint(columnNames = "isbn"),
        indexes = @Index(columnList = "member_id"))
class LoanEntity {
    @Id
    private UUID id;
    @Column(name = "member_id", nullable = false)
    private String memberId;
    @Column(nullable = false)
    private String isbn;
    @Column(name = "borrowed_at", nullable = false)
    private Instant borrowedAt;

    protected LoanEntity() {}

    LoanEntity(UUID id, String memberId, String isbn, Instant borrowedAt) {
        this.id = id;
        this.memberId = memberId;
        this.isbn = isbn;
        this.borrowedAt = borrowedAt;
    }
}
E
cat > $I/SpringDataLoanRepository.java <<E
package $IP;

import java.util.UUID;
import org.springframework.data.jpa.repository.JpaRepository;

interface SpringDataLoanRepository extends JpaRepository<LoanEntity, UUID> {
    int countByMemberId(String memberId);

    boolean existsByIsbn(String isbn);
}
E
cat > $I/JpaLoanRepository.java <<E
package $IP;

import com.example.library.domain.loan.*;

public class JpaLoanRepository implements LoanRepository {
    private final SpringDataLoanRepository jpa;

    public JpaLoanRepository(SpringDataLoanRepository jpa) {
        this.jpa = jpa;
    }

    @Override
    public int countByMember(MemberId memberId) {
        return jpa.countByMemberId(memberId.value());
    }

    @Override
    public boolean existsByIsbn(Isbn isbn) {
        return jpa.existsByIsbn(isbn.value());
    }

    @Override
    public void save(Loan loan) {
        jpa.saveAndFlush(new LoanEntity(loan.id().value(), loan.memberId().value(),
                loan.isbn().value(), loan.borrowedAt()));
    }
}
E

