package $WP.loan;

import com.example.library.application.loan.BorrowBook;
import com.example.library.domain.loan.LoanRepository;
import com.example.library.infrastructure.loan.JpaLoanRepositoryFactory;
import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;
import org.springframework.boot.autoconfigure.domain.EntityScan;

@Configuration
@EntityScan("com.example.library.infrastructure")
@EnableJpaRepositories("com.example.library.infrastructure")
class LoanConfiguration {
    @Bean
    Clock clock() {
        return Clock.systemUTC();
    }

    @Bean
    LoanRepository loanRepository(JpaLoanRepositoryFactory factory) {
        return factory.create();
    }

    @Bean
    BorrowBook borrowBook(LoanRepository loans, Clock clock) {
        return new BorrowBook(loans, clock);
    }
}
