@RestController
@RequestMapping("/loans")
class LoanController {
    record BorrowRequest(String memberId, String isbn) {}

    record BorrowResponse(String loanId) {}

    private final BorrowBook borrowBook;

    LoanController(BorrowBook borrowBook) {
        this.borrowBook = borrowBook;
    }

