package com.example.library.api.loan;

import com.example.library.domain.loan.BookAlreadyOnLoanException;
import com.example.library.domain.loan.LoanLimitExceededException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
class LoanExceptionHandler {
    @ExceptionHandler({BookAlreadyOnLoanException.class, LoanLimitExceededException.class,
            DataIntegrityViolationException.class})
    ProblemDetail conflict(Exception e) {
        String detail = e instanceof DataIntegrityViolationException
                ? "Book is already on loan" : e.getMessage();
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, detail);
    }

    @ExceptionHandler(IllegalArgumentException.class)
    ProblemDetail badRequest(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }
}
