package com.example.library.api.loan;

import com.example.library.application.loan.BorrowBook;
import com.example.library.domain.loan.Isbn;
import com.example.library.domain.loan.LoanId;
import com.example.library.domain.loan.MemberId;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/loans")
class LoanController {
    record BorrowRequest(String memberId, String isbn) {}

    record BorrowResponse(String loanId) {}

    private final BorrowBook borrowBook;

    LoanController(BorrowBook borrowBook) {
        this.borrowBook = borrowBook;
    }

    @PostMapping
    @Transactional
    ResponseEntity<BorrowResponse> borrow(@RequestBody BorrowRequest request) {
        LoanId id = LoanId.generate();
        borrowBook.execute(id, new MemberId(request.memberId()), new Isbn(request.isbn()));
        return ResponseEntity.status(HttpStatus.CREATED).body(new BorrowResponse(id.value().toString()));
    }
}
